export async function loadEntries(basePath: string): Promise<MarkdownEntry[]> {
  const creds = getCredentials();
  if (!creds) {
    return [];
  }

  try {
    const response = await fetch(`${API_BASE_URL}/filesmd`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username: creds.username, password: creds.password, basePath }),
    });

    if (!response.ok) {
      const data = await response.json();
      console.error('加载条目失败:', data.error);
      // 网络失败时回退到本地缓存
      const cached = localStorage.getItem(LOCAL_CACHE_KEY);
      if (cached) {
        try { return JSON.parse(cached); } catch { /* ignore */ }
      }
      return [];
    }

    const data = await response.json();
    const allEntries: MarkdownEntry[] = [];

    for (const { fileName, content } of data.entries || []) {
      const entries = parseMarkdownFile(content, fileName);
      allEntries.push(...entries);
    }

    localStorage.setItem(LOCAL_CACHE_KEY, JSON.stringify(allEntries));
    return allEntries;
  } catch (error) {
    console.error('加载条目失败:', error);
    // 网络失败时回退到本地缓存
    const cached = localStorage.getItem(LOCAL_CACHE_KEY);
    if (cached) {
      try { return JSON.parse(cached); } catch { /* ignore */ }
    }
    return [];
  }
}


export async function appendToFile(basePath: string, content: string, type: 'chat' | 'todo' | 'journal'): Promise<boolean> {
  const creds = getCredentials();
  if (!creds) {
    return false;
  }

  try {
    let filePath = '';

    if (type === 'chat') {
      filePath = `${basePath}/Chat.md`;
    } else if (type === 'todo') {
      filePath = `${basePath}/Later.md`;
    } else if (type === 'journal') {
      const now = new Date();
      const year = now.getFullYear();
      const month = String(now.getMonth() + 1).padStart(2, '0');
      filePath = `${basePath}/journal/${year}.${month}.md`;
    }

    const readResponse = await fetch(`${API_BASE_URL}/read`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username: creds.username, password: creds.password, filePath }),
    });

    let existingContent = '';
    if (readResponse.ok) {
      const data = await readResponse.json();
      existingContent = data.content || '';
    } else if (readResponse.status !== 404) {
      return false;
    }

    const newContent = existingContent.trimEnd() + '\n' + content;

    const writeResponse = await fetch(`${API_BASE_URL}/write`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username: creds.username, password: creds.password, filePath, content: newContent }),
    });

    if (writeResponse.ok) {
      localStorage.removeItem(LOCAL_CACHE_KEY);
      return true;
    }

    if (writeResponse.status === 409) {
      const dirPath = filePath.substring(0, filePath.lastIndexOf('/'));
      const mkdirResponse = await fetch(`${API_BASE_URL}/mkdir`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: creds.username, password: creds.password, dirPath }),
      });

      if (mkdirResponse.ok || mkdirResponse.status === 405) {
        const retryWriteResponse = await fetch(`${API_BASE_URL}/write`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ username: creds.username, password: creds.password, filePath, content: newContent }),
        });

        if (retryWriteResponse.ok) {
          localStorage.removeItem(LOCAL_CACHE_KEY);
          return true;
        }
      }
    }

    return false;
  } catch {
    return false;
  }
}
export interface UpdateResult {
  success: boolean;
  error?: string;
}

export async function updateFileContent(
  basePath: string,
  fileName: string,
  oldContent: string,
  newContent: string
): Promise<UpdateResult> {
  if (!oldContent) {
    return { success: false, error: '原始内容为空，无法定位待修改行' };
  }
  if (newContent === oldContent) {
    return { success: false, error: '内容未发生变化' };
  }

  const creds = getCredentials();
  if (!creds) {
    return { success: false, error: '未配置坚果云账号' };
  }

  let filePath = '';
  if (fileName === 'Chat.md') {
    filePath = `${basePath}/Chat.md`;
  } else if (fileName === 'Later.md') {
    filePath = `${basePath}/Later.md`;
  } else if (fileName.includes('journal') || fileName.match(/\d{4}\.\d{2}/)) {
    filePath = `${basePath}/journal/${fileName}`;
  } else {
    filePath = `${basePath}/${fileName}`;
  }

  try {
    const readResponse = await fetch(`${API_BASE_URL}/read`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username: creds.username, password: creds.password, filePath }),
    });

    if (!readResponse.ok) {
      const errData = await readResponse.json().catch(() => ({}));
      return {
        success: false,
        error: `读取文件失败(${readResponse.status}): ${errData.error || readResponse.statusText}`,
      };
    }
    const data = await readResponse.json();
    const fileContent: string = data.content || '';

    // 多级匹配策略：精确匹配 -> trim匹配 -> 包含匹配 -> 内容匹配
    const lines = fileContent.split('\n');
    const trimmedOld = oldContent.trim();
    let matchedIndex = -1;

    // 第1级：精确匹配
    for (let i = 0; i < lines.length; i++) {
      if (lines[i] === oldContent) {
        matchedIndex = i;
        break;
      }
    }

    // 第2级：trim后精确匹配
    if (matchedIndex === -1) {
      for (let i = 0; i < lines.length; i++) {
        if (lines[i].trim() === trimmedOld) {
          matchedIndex = i;
          break;
        }
      }
    }

    // 第3级：包含关系匹配（行内容包含oldContent或oldContent包含行内容）
    if (matchedIndex === -1 && trimmedOld.length > 2) {
      for (let i = 0; i < lines.length; i++) {
        const lineTrimmed = lines[i].trim();
        if (lineTrimmed.includes(trimmedOld) || trimmedOld.includes(lineTrimmed)) {
          matchedIndex = i;
          break;
        }
      }
    }

    // 第4级：用 entry.content 匹配（去掉时间戳等前缀）
    if (matchedIndex === -1) {
      const contentOnly = oldContent.replace(/^\d{1,2}:\d{2}\s*-?\s*/, '').trim();
      if (contentOnly && contentOnly !== trimmedOld) {
        for (let i = 0; i < lines.length; i++) {
          if (lines[i].trim() === contentOnly || lines[i].trim().includes(contentOnly)) {
            matchedIndex = i;
            break;
          }
        }
      }
    }

    if (matchedIndex === -1) {
      return {
        success: false,
        error: '原始行在文件中未找到（可能已被其他设备修改，请刷新后重试）',
      };
    }

    // 用原始行进行替换（保留原始行的前后空格）
    const originalLine = lines[matchedIndex];
    const updatedContent = fileContent.replace(originalLine, () => newContent);

    if (updatedContent === fileContent) {
      return { success: false, error: '内容替换失败' };
    }

    const writeResponse = await fetch(`${API_BASE_URL}/write`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        username: creds.username,
        password: creds.password,
        filePath,
        content: updatedContent,
      }),
    });

    if (writeResponse.ok) {
      localStorage.removeItem(LOCAL_CACHE_KEY);
      return { success: true };
    }

    const errData = await writeResponse.json().catch(() => ({}));
    return {
      success: false,
      error: `写入失败(${writeResponse.status}): ${errData.error || writeResponse.statusText}`,
    };
  } catch (error) {
    return {
      success: false,
      error: `网络异常: ${error instanceof Error ? error.message : '未知错误'}`,
    };
  }
}


export async function deleteFileContent(
  basePath: string,
  fileName: string,
  content: string
): Promise<UpdateResult> {
  if (!content) {
    return { success: false, error: '删除内容为空' };
  }

  const creds = getCredentials();
  if (!creds) {
    return { success: false, error: '未配置坚果云账号' };
  }

  let filePath = '';
  if (fileName === 'Chat.md') {
    filePath = basePath + '/Chat.md';
  } else if (fileName === 'Later.md') {
    filePath = basePath + '/Later.md';
  } else if (fileName.includes('journal') || fileName.match(/\d{4}\.\d{2}/)) {
    filePath = basePath + '/journal/' + fileName;
  } else {
    filePath = basePath + '/' + fileName;
  }

  try {
    const readResponse = await fetch(API_BASE_URL + '/read', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username: creds.username, password: creds.password, filePath }),
    });

    if (!readResponse.ok) {
      return { success: false, error: '读取文件失败，无法删除' };
    }
    const data = await readResponse.json();
    const fileContent = data.content || '';

    const lines = fileContent.split('\n');
    const trimmedContent = content.trim();
    let matchedIndex = -1;

    for (let i = 0; i < lines.length; i++) {
      if (lines[i] === content) { matchedIndex = i; break; }
    }
    if (matchedIndex === -1) {
      for (let i = 0; i < lines.length; i++) {
        if (lines[i].trim() === trimmedContent) { matchedIndex = i; break; }
      }
    }
    if (matchedIndex === -1 && trimmedContent.length > 2) {
      for (let i = 0; i < lines.length; i++) {
        const lt = lines[i].trim();
        if (lt.includes(trimmedContent) || trimmedContent.includes(lt)) { matchedIndex = i; break; }
      }
    }
    if (matchedIndex === -1) {
      const contentOnly = content.replace(/^\d{1,2}:\d{2}\s*-?\s*/, '').trim();
      if (contentOnly && contentOnly !== trimmedContent) {
        for (let i = 0; i < lines.length; i++) {
          if (lines[i].trim() === contentOnly || lines[i].trim().includes(contentOnly)) { matchedIndex = i; break; }
        }
      }
    }

    if (matchedIndex === -1) {
      return { success: false, error: '未找到要删除的内容（可能已被其他设备修改）' };
    }

    lines.splice(matchedIndex, 1);
    while (matchedIndex > 0 && lines[matchedIndex - 1].trim() === '' && lines[matchedIndex] && lines[matchedIndex].trim() === '') {
      lines.splice(matchedIndex - 1, 1);
      matchedIndex--;
    }
    const updatedContent = lines.join('\n');

    const writeResponse = await fetch(API_BASE_URL + '/write', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username: creds.username, password: creds.password, filePath, content: updatedContent }),
    });

    if (writeResponse.ok) {
      localStorage.removeItem(LOCAL_CACHE_KEY);
      return { success: true };
    }
    return { success: false, error: '写入失败，删除未生效' };
  } catch (error) {
    return { success: false, error: '网络异常: ' + (error instanceof Error ? error.message : '未知错误') };
  }
}
